// BOZP Audit 4.2: catalog seeded from supplied examples. Intervals editable, not a statement of statutory validity.
E.typeGroup='all';E.typeQuery='';E.matrixGroup='Základné školenia';
const groupTitle=g=>['BOZP','PO','Základné školenia'].includes(g)?'Základné školenia':g==='Odborné školenia'?'Odborné školenia':(g||'Ostatné');
function trainingGroups(){return [...new Set(db.trainingTypes.map(t=>groupTitle(t.group)))].sort((a,b)=>a==='Základné školenia'?-1:b==='Základné školenia'?1:a==='Odborné školenia'?-1:1)}
