window.empCatalogSearch=v=>{E.typeQuery=v;const el=document.querySelector('#emp-type-list');if(el)el.innerHTML=catalogRows();const count=document.querySelector('#emp-type-count');if(count)count.textContent=filterCatalog().length+' školení';};
function filterCatalog(){return db.trainingTypes.filter(t=>(E.typeGroup==='all'||groupTitle(t.group)===E.typeGroup)&&(!E.typeQuery||`${t.name} ${t.group}`.toLocaleLowerCase('sk').includes(E.typeQuery.toLocaleLowerCase('sk')))).sort((a,b)=>a.name.localeCompare(b.name,'sk'))}
function catalogRows(){const list=filterCatalog();return list.length?list.map(t=>`<article class="emp-catalog-item"><span class="emp-catalog-icon">${groupTitle(t.group)==='Základné školenia'?'📘':'🎓'}</span><div class="emp-catalog-copy"><b>${safe(t.name)}</b><small>${safe(groupTitle(t.group))} · Prednastavené: ${t.months?`${t.months} mesiacov`:'neurčené'} · možnosť zmeny</small></div><button class="emp-btn plain" onclick="empEditType('${safe(t.id)}')">Upraviť</button>${!['bozp','po'].includes(t.id)?`<button class="emp-link emp-delete-inline" onclick="empDeleteType('${safe(t.id)}')" aria-label="Vymazať ${escAttr(t.name)}">✕</button>`:''}</article>`).join(''):'<div class="emp-note">Žiadne školenia nevyhovujú filtru.</div>'}
window.empOpenTypes=()=>{ensure();const groups=trainingGroups();modal('Katalóg školení','PREHĽADNÉ NASTAVENIA · LEHOTY',`<div class="emp-catalog-intro"><b>Východiskový katalóg podľa tvojej tabuľky</b><p>Uvedené intervaly sú editovateľné predvoľby, nie automatické potvrdenie zákonnej periodicity. Termíny vždy over podľa konkrétnej činnosti a odborného predpisu. Existujúce záznamy sa zmenou katalógu nemažú.</p></div><div class="emp-catalog-toolbar"><div class="emp-catalog-tabs"><button class="${E.typeGroup==='all'?'active':''}" onclick="empCatalogGroup('all')">Všetky</button>${groups.map(g=>`<button class="${E.typeGroup===g?'active':''}" onclick="empCatalogGroup('${safe(g).replace(/'/g,'&#39;')}')">${safe(g)}</button>`).join('')}</div><label class="emp-control">Hľadať školenie<input type="search" value="${escAttr(E.typeQuery)}" oninput="empCatalogSearch(this.value)" placeholder="Napr. VZV, žeriavy, BOZP…"></label></div><div class="emp-inline" style="justify-content:space-between;margin:14px 0"><strong id="emp-type-count">${filterCatalog().length} školení</strong><button class="emp-btn primary" onclick="empEditType()">＋ Vlastné školenie</button></div><div class="emp-catalog-list" id="emp-type-list">${catalogRows()}</div>`, '',true)};
window.empEditType=id=>{ensure();const t=db.trainingTypes.find(x=>x.id===id)||{};const gs=[...new Set(['Základné školenia','Odborné školenia','Ostatné',...trainingGroups()])];modal(id?'Upraviť školenie':'Nové školenie','KATALÓG · UPRAVITEĽNÉ TERMÍNY',`<form id="emp-type-form" onsubmit="event.preventDefault();empSaveType('${safe(id||'')}')"><label class="emp-control">Názov školenia *<input name="name" required maxlength="220" value="${escAttr(t.name||'')}" placeholder="Napr. Obsluha VZV"></label><div class="emp-grid" style="margin-top:13px"><label class="emp-control">Kategória<select name="group">${gs.map(g=>`<option value="${safe(g)}" ${groupTitle(t.group)===g?'selected':''}>${safe(g)}</option>`).join('')}</select></label><label class="emp-control">Opakovanie po (mesiace)<input name="months" type="number" min="0" max="240" value="${t.months??''}" placeholder="0 = bez periodicity"></label></div><div class="emp-note">Termín si môžeš upraviť v katalógu. Pri konkrétnom zamestnancovi možno nastaviť aj individuálny dátum platnosti.</div><div class="emp-inline" style="justify-content:flex-end"><button type="button" class="emp-btn" onclick="empOpenTypes()">Späť</button><button type="submit" class="emp-btn primary">Uložiť školenie</button></div></form>`) };
window.empMatrixGroup=g=>{E.matrixGroup=g;empOpenMatrix()};
window.empOpenMatrix=()=>{ensure();const roles=companyPositions(),groups=trainingGroups();if(!groups.includes(E.matrixGroup))E.matrixGroup=groups[0]||'Základné školenia';const types=db.trainingTypes.filter(t=>groupTitle(t.group)===E.matrixGroup).sort((a,b)=>a.name.localeCompare(b.name,'sk'));modal('Matica školení podľa profesií','FIRMA: '+companyName(E.company),`<div class="emp-matrix-help"><b>Profesia × požadované školenie</b><p>V riadkoch sú profesie a v stĺpcoch školenia. Označenie sa ihneď ukladá; história absolvovaných školení zostáva zachovaná.</p><div class="emp-inline"><button class="emp-btn" onclick="empEditPosition()">＋ Nová profesia</button><button class="emp-btn" onclick="empOpenTypes()">⚙ Upraviť katalóg</button></div></div><div class="emp-matrix-pills">${groups.map(g=>`<button class="${E.matrixGroup===g?'selected':''}" onclick="empMatrixGroup('${safe(g)}')">${safe(g)} <small>${db.trainingTypes.filter(t=>groupTitle(t.group)===g).length}</small></button>`).join('')}</div>${roles.length?`<div class="emp-matrix-scroll"><table class="emp-matrix"><thead><tr><th class="emp-sticky">Profesia / školenie</th>${types.map(t=>`<th title="${escAttr(t.name)}"><span>${safe(t.name)}</span><small>${t.months?t.months+' mes.':'individuálne'}</small></th>`).join('')}</tr></thead><tbody>${roles.map(p=>`<tr><th class="emp-sticky"><b>${safe(p.name)}</b><small>${db.employees.filter(e=>e.companyId===E.company&&(e.professionId===p.id||e.role===p.name)).length} zamestnancov</small></th>${types.map(t=>`<td><label class="emp-matrix-checkbox" title="${escAttr(p.name)}: ${escAttr(t.name)}"><input type="checkbox" ${p.trainingTypeIds?.includes(t.id)?'checked':''} onchange="empMatrixToggle('${safe(p.id)}','${safe(t.id)}',this.checked)"><span aria-hidden="true">✓</span></label></td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="emp-note">Najprv pridaj profesie k tejto firme.</div>'}<p class="emp-help">Poznámka: výber školení v matici určuje internú požiadavku pracoviska. Nejde o automatické osvedčenie odbornej spôsobilosti.</p>`, '',true)};
